#!/usr/bin/env python3
import importlib.util, json, random, sys

def load(name, path):
    spec = importlib.util.spec_from_file_location(name, path)
    mod = importlib.util.module_from_spec(spec); spec.loader.exec_module(mod)
    return mod

mn = load("mainsub", "/work/submission/main.py")
rf = load("refmod", "/work/tmp/dev/ref.py")
g2 = load("gen2", "/work/tmp/dev/gen2.py")

def deep(o):
    return json.loads(json.dumps(o))

def diff(a, b, tag, doc):
    if a == b: return False
    print("MISMATCH", tag)
    for k in ("rounds","metrics","classes","summary"):
        if a.get(k) != b.get(k):
            print(" key:", k)
            print("  main:", json.dumps(a.get(k))[:2000])
            print("  ref :", json.dumps(b.get(k))[:2000])
    with open("/work/tmp/dev/fail_%s.json" % tag.replace(" ","_"), "w") as f:
        json.dump(doc, f, indent=1)
    return True

def run(seed0, count, big=False):
    bad = 0
    stats = {}
    for i in range(count):
        rng = random.Random(seed0 + i)
        doc = g2.gen(rng, big)
        try:
            a = mn.run(deep(doc)); ea = None
        except mn.BadInput as e:
            a = None; ea = "BAD:" + str(e)
        except Exception as e:
            a = None; ea = "MAINEXC:" + repr(e)
        try:
            b = rf.run(deep(doc)); eb = None
        except Exception as e:
            b = None; eb = "REFEXC:" + repr(e)
        if ea or eb:
            print("seed", seed0+i, "status", ea, eb)
            bad += 1; continue
        if a["summary"]["coverage_status"] == "complete": stats["complete"] = stats.get("complete",0)+1
        if a["summary"]["ambiguous_observed_classes"]: stats["amb"] = stats.get("amb",0)+1
        if a["metrics"]["late_ping"]: stats["late"] = stats.get("late",0)+1
        if diff(a, b, "seed%d" % (seed0+i), doc):
            bad += 1
            if bad > 3: break
    print("done count=%d failures=%d stats=%s" % (count, bad, stats))
    return bad

if __name__ == "__main__":
    seed0 = int(sys.argv[1]); count = int(sys.argv[2])
    big = len(sys.argv) > 3 and sys.argv[3] == "big"
    sys.exit(1 if run(seed0, count, big) else 0)
PYEOF
